// Teacher experiment: ideal body and swing-foot positions feed shared Rust
// linkage corrections. Registered servo dynamics remain active.
fn control(t, sensors, commands, state) {
    let joint_gain = sensors["command.tracking_gain"];
    // The typed Rust observations below are privileged simulated forces (N).
    // Preserve moving gain; strengthen stop/stand correction with four supports.
    let p = parameters();
    let support = 1.0;
    for name in p.support_force_channels {
        support = support.min((sensors[name] / p.full_support_force_n).max(0.0).min(1.0));
    }
    let stopped = true;
    for name in p.motion_command_channels { if sensors[name] != 0.0 { stopped = false; } }
    let extra_gain = if stopped { p.standing_gain_increment * support } else { 0.0 };
    let body_gain = sensors["command.body_gain"] + extra_gain;
    for name in commands.keys() {
        let joint = name.sub_string(0, name.len() - 7);
        let reference = sensors[joint + ".reference"];
        commands[name] = reference
            + joint_gain * (reference - sensors[joint + ".angle"])
            + body_gain * sensors[joint + ".body_correction"]
            + sensors["command.point_gain"] * sensors[joint + ".point_correction"];
        // Residual is an angle command, still subject to software/CAD bounds.
        // Preserve the original arithmetic exactly when no correction is requested.
        let residual = sensors[p.residual_input_by_target[name]];
        if residual != 0.0 { commands[name] += residual; }
    }
    #{commands: commands, state: state}
}
